using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Unity.Profiling;
public static class SavedTreeBatchCheck {
 static Camera camera;static Vector3 oldPosition;static Quaternion oldRotation;static MonoBehaviour movement;static bool oldMovement;static EditorWindow window;static bool maximized,background;static int frame=-1,view,vsync,rate;static double start,batches,triangles;static int count;static ProfilerRecorder batch,tri;static string result="view,batches,triangles,frames\n";
 public static object Run(){if(!EditorApplication.isPlaying)throw new Exception("Play Mode required");camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.name=="Camera");oldPosition=camera.transform.position;oldRotation=camera.transform.rotation;movement=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).FirstOrDefault(m=>m.GetType().Name=="KarakterHareket");oldMovement=movement&&movement.enabled;if(movement)movement.enabled=false;window=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));maximized=window.maximized;window.maximized=true;window.Focus();background=Application.runInBackground;rate=Application.targetFrameRate;vsync=QualitySettings.vSyncCount;Application.runInBackground=true;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;batch=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Batches Count",1);tri=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Triangles Count",1);Next();EditorApplication.update+=Tick;return "Started saved asset runtime check";}
 static void Next(){camera.transform.SetPositionAndRotation(view==0?new Vector3(509.513f,2.235f,1248.762f):new Vector3(465,3,912),Quaternion.Euler(0,view==0?180:270,0));start=EditorApplication.timeSinceStartup;batches=triangles=0;count=0;}
 static void Finish(){EditorApplication.update-=Tick;if(camera)camera.transform.SetPositionAndRotation(oldPosition,oldRotation);if(movement)movement.enabled=oldMovement;window.maximized=maximized;Application.runInBackground=background;Application.targetFrameRate=rate;QualitySettings.vSyncCount=vsync;batch.Dispose();tri.Dispose();File.WriteAllText("Recovery/DrawCalls_20261107/SavedBatchCheck.csv",result);File.WriteAllText("Recovery/DrawCalls_20261107/SavedBatchCheck.status","COMPLETE");}
 static void Tick(){try{if(!EditorApplication.isPlaying){Finish();return;}if(Time.frameCount==frame)return;frame=Time.frameCount;double elapsed=EditorApplication.timeSinceStartup-start;if(elapsed<5)return;if(elapsed<9){batches+=batch.LastValue;triangles+=tri.LastValue;count++;return;}if(count>0)result+=view+","+(batches/count).ToString(System.Globalization.CultureInfo.InvariantCulture)+","+(triangles/count).ToString(System.Globalization.CultureInfo.InvariantCulture)+","+count+"\n";if(++view>=2)Finish();else Next();}catch(Exception e){Finish();File.WriteAllText("Recovery/DrawCalls_20261107/SavedBatchCheck.status","ERROR "+e);}}
}
